const app=document.querySelector('#app');
const safe=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const list=items=>`<ul>${items.map(item=>`<li>${safe(item)}</li>`).join('')}</ul>`;
const chosen=new Set();
const filters={query:'',sector:'all',stage:'all'};
const sectors=[...new Set(jobs.map(job=>job.sector))].sort((a,b)=>a.localeCompare(b,'es'));
const sourceLinks=job=>job.src.map(key=>`<a href="${sources[key].url}" target="_blank" rel="noopener">${safe(sources[key].label)} ↗</a>`).join('');
const jobUrl=job=>`/profesion/?id=${encodeURIComponent(job.id)}`;

function tile(job){const selected=chosen.has(job.id);const full=chosen.size===2&&!selected;return `<article class="card"><div class="card-top"><span class="job-icon" aria-hidden="true">${job.icon}</span><span class="sector-pill">${safe(job.sector)}</span></div><h3>${safe(job.name)}</h3><p>${safe(job.summary)}</p><div class="card-bottom"><a class="text-button" href="${jobUrl(job)}" aria-label="Ver ficha de ${safe(job.name)}">Ver ficha ↗</a><button class="compare-button ${selected?'selected':''}" data-choose="${job.id}" aria-pressed="${selected}" ${full?'disabled title="Quita una profesión para elegir otra"':''} aria-label="${selected?'Quitar':'Añadir'} ${safe(job.name)} ${selected?'de':'a'} la comparación">${selected?'− Quitar':full?'Máximo 2':'＋ Elegir'}</button></div></article>`}
function home(){return `<div class="home-view"><section class="hero"><div class="hero-copy"><p class="eyebrow">ORIENTACIÓN LABORAL · ESPAÑA</p><h1>Descubre lo que te <em>gustaría hacer.</em></h1><p class="lead">Explora trabajos, habilidades y estudios. El camino lo eliges tú.</p><a class="primary" href="/explorar/">Ver profesiones <span aria-hidden="true">↗</span></a><div class="hero-foot"><span>10 profesiones</span><span class="divider"></span><span>Muchos caminos</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-label art-label-one">LO QUE TE GUSTA</span><span class="art-label art-label-two">LO QUE APRENDES</span><div class="compass"><span>✦</span></div></div></section><section class="section home-featured"><div class="section-intro"><div><p class="eyebrow">PARA EMPEZAR</p><h2>Por dónde mirar.</h2></div><a class="section-link" href="/explorar/">Todas las profesiones ↗</a></div><div class="cards">${[jobs[0],jobs[1],jobs[3],jobs[9]].map(tile).join('')}</div></section><section class="home-next"><div><p class="eyebrow">SI AÚN NO LO TIENES CLARO</p><h2>Prueba, compara, pregunta.</h2><p>Ninguna ficha decide por ti. Úsalas para descubrir qué te atrae y qué quieres averiguar después.</p></div><a href="/comparar/">Comparar opciones ↗</a></section></div>`}
function filteredJobs(){const q=filters.query.trim().toLocaleLowerCase('es');return jobs.filter(job=>(filters.sector==='all'||job.sector===filters.sector)&&(filters.stage==='all'||job.stage.includes(filters.stage))&&(!q||[job.name,job.sector,job.summary,...job.tasks,...job.skills,...job.routes].join(' ').toLocaleLowerCase('es').includes(q)))}
function explorer(){return `<section class="section page-view explore"><div class="page-heading"><p class="eyebrow">EXPLORA</p><h1>Profesiones</h1><p>Busca por trabajo, sector o habilidad.</p></div><div class="controls"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="¿Qué te interesa?" autocomplete="off" aria-label="Buscar profesiones" value="${safe(filters.query)}"></label><label class="select-wrap">Sector <select id="sector"><option value="all">Todos</option>${sectors.map(name=>`<option value="${safe(name)}" ${filters.sector===name?'selected':''}>${safe(name)}</option>`).join('')}</select></label><label class="select-wrap">Etapa <select id="stage"><option value="all">Todas</option><option value="eso" ${filters.stage==='eso'?'selected':''}>ESO</option><option value="bach" ${filters.stage==='bach'?'selected':''}>Bachillerato</option><option value="fp" ${filters.stage==='fp'?'selected':''}>FP</option><option value="adulto" ${filters.stage==='adulto'?'selected':''}>Cambio profesional</option></select></label></div><div class="results-line"><strong id="count"></strong><a href="/comparar/">Comparar elegidas <span id="inline-count">(${chosen.size})</span> ↗</a></div><div id="cards" class="cards" aria-live="polite"></div><p id="empty" class="empty" hidden>Sin resultados. Prueba otra búsqueda.</p><p class="catalog-note">Fichas de ejemplo, aún sin revisión individual. <a href="/recursos/">Ver fuentes ↗</a></p></section>`}
function detail(job){if(!job)return `<section class="section page-view"><p class="eyebrow">FICHA</p><h1>No encontramos esa profesión.</h1><a class="primary" href="/explorar/">Volver al catálogo ↗</a></section>`;const full=chosen.size===2&&!chosen.has(job.id);return `<article class="section page-view detail-page"><a class="back-link" href="/explorar/">← Profesiones</a><div class="detail-hero"><div><p class="eyebrow">${safe(job.sector)} · FICHA DE EJEMPLO</p><h1>${safe(job.name)}</h1><p class="lead">${safe(job.summary)}</p><div class="detail-actions"><button class="primary button-primary" data-choose="${job.id}" ${full?'disabled title="Quita una profesión para elegir otra"':''}>${chosen.has(job.id)?'− Quitar de comparación':full?'Máximo 2':'＋ Elegir para comparar'}</button><a href="/comparar/">Ir a la comparación ↗</a></div></div><span class="detail-symbol" aria-hidden="true">${job.icon}</span></div><div class="detail-grid"><section><h2>Qué harías</h2>${list(job.tasks)}</section><section><h2>Qué aprenderías</h2>${list(job.skills)}</section><section class="wide"><h2>Cómo llegar</h2>${list(job.routes)}${job.regulated?'<p class="warning">Esta profesión tiene requisitos de ejercicio. Verifícalos en fuentes oficiales.</p>':''}</section></div><div class="detail-sources"><strong>Para seguir investigando</strong>${sourceLinks(job)}<small>Fuentes generales. Esta ficha aún necesita revisión específica.</small></div></article>`}
function comparison(){const selected=[...chosen].map(id=>jobs.find(job=>job.id===id));return `<section class="section page-view compare-page"><div class="page-heading"><p class="eyebrow">COMPARA</p><h1>Dos caminos</h1><p>Habilidades y vías de estudio, frente a frente.</p></div>${selected.length?`<div class="comparison">${selected.map(job=>`<article class="compare-column"><div class="compare-title"><span class="job-icon">${job.icon}</span><div><small>${safe(job.sector)}</small><h2>${safe(job.name)}</h2></div><button data-choose="${job.id}" aria-label="Quitar ${safe(job.name)}">×</button></div><h3>Habilidades</h3>${list(job.skills)}<h3>Estudios y vías</h3>${list(job.routes)}<a class="text-button" href="${jobUrl(job)}">Ver ficha ↗</a></article>`).join('')}${selected.length===1?'<div class="compare-placeholder second"><p>Falta una profesión.</p><a class="primary" href="/explorar/">Elegir otra ↗</a></div>':''}</div>`:`<div class="compare-empty"><span aria-hidden="true">⇄</span><h2>¿Qué quieres comparar?</h2><p>Elige hasta dos profesiones.</p><a class="primary" href="/explorar/">Elegir profesiones ↗</a></div>`}</section>`}
function resources(){return `<section class="section page-view resources-page"><div class="page-heading"><p class="eyebrow">FUENTES</p><h1>Para seguir buscando</h1><p>Herramientas públicas para dar el siguiente paso.</p></div><div class="resource-grid"><a class="resource-card" href="${sources.fp.url}" target="_blank" rel="noopener"><span class="resource-icon">01</span><h2>Estudios de FP</h2><p>Busca títulos y certificados en TodoFP.</p><strong>Abrir TodoFP ↗</strong></a><a class="resource-card" href="${sources.needs.url}" target="_blank" rel="noopener"><span class="resource-icon">02</span><h2>Habilidades demandadas</h2><p>Consulta las necesidades formativas del SEPE.</p><strong>Abrir SEPE ↗</strong></a><a class="resource-card" href="https://www.ine.es/dynt3/inebase/index.htm?capsel=4568&padre=4563" target="_blank" rel="noopener"><span class="resource-icon">03</span><h2>Salarios en España</h2><p>Datos del INE por grupos de ocupación, no por ficha.</p><strong>Abrir INE ↗</strong></a></div><p class="resource-note">Las fichas de Brújula son ejemplos orientativos. Verifica cada vía y requisito antes de matricularte.</p></section>`}
const mock=[{name:'Salud',views:142},{name:'Tecnología',views:104},{name:'Educación',views:78},{name:'Industria y energía',views:64},{name:'Otros sectores',views:92}];
function centers(){const total=mock.reduce((sum,row)=>sum+row.views,0);return `<section class="section page-view centers-page"><div class="page-heading"><p class="eyebrow">PARA CENTROS</p><h1>Intereses en conjunto</h1><p>Un ejemplo de lo que un centro podría consultar.</p></div><div class="mock-banner"><strong>Datos simulados</strong><span>Esta pantalla no refleja visitas reales ni datos de alumnos.</span></div><div class="dashboard-grid"><article class="stat-card"><span>Consultas de fichas</span><strong>${total}</strong><small>Ejemplo · últimos 30 días</small></article><article class="stat-card"><span>Sectores explorados</span><strong>9</strong><small>Interés repartido entre áreas</small></article><article class="stat-card"><span>Opciones comparadas</span><strong>86</strong><small>Comparaciones iniciadas</small></article></div><div class="insight-grid"><article class="insight-panel"><div class="panel-title"><h2>Interés por sector</h2><span>Consultas</span></div><div class="bars">${mock.map(row=>`<div class="bar-row"><span>${safe(row.name)}</span><div class="bar-track"><i style="width:${Math.round(row.views/mock[0].views*100)}%"></i></div><strong>${row.views}</strong></div>`).join('')}</div><p class="panel-note">Las categorías pequeñas se reúnen en “Otros sectores”.</p></article><article class="insight-panel"><div class="panel-title"><h2>Fichas más vistas</h2><span>Ejemplo</span></div><ol class="rank-list"><li><span>Enfermería</span><strong>72</strong></li><li><span>Desarrollo de software</span><strong>61</strong></li><li><span>Docencia de primaria</span><strong>45</strong></li><li><span>Electricista</span><strong>38</strong></li></ol><p class="panel-note">Sirve para detectar interés, no para evaluar a nadie.</p></article></div><div class="privacy-panel"><div><h2>Qué podríamos medir</h2><p>Fichas consultadas, sectores elegidos y comparaciones. Solo recuentos agregados, sin nombres ni historiales individuales.</p></div><div><h2>Qué no hacemos hoy</h2><p>Este MVP no recopila eventos. Antes de medir habría que definir privacidad, informar claramente y proteger especialmente a menores.</p></div></div></section>`}
function currentRoute(){const path=location.pathname;return path.startsWith('/explorar')?'explorar':path.startsWith('/profesion')?'profesion':path.startsWith('/comparar')?'comparar':path.startsWith('/centros')?'centros':path.startsWith('/recursos')||path.startsWith('/criterios')?'recursos':'inicio'}
function render(){const route=currentRoute();const job=route==='profesion'?jobs.find(item=>item.id===new URLSearchParams(location.search).get('id')):null;const views={inicio:home,explorar:explorer,profesion:()=>detail(job),comparar:comparison,centros:centers,recursos:resources};app.innerHTML=views[route]();document.title=`${route==='inicio'?'Inicio':route==='profesion'?(job?.name||'Ficha'):route==='explorar'?'Profesiones':route==='comparar'?'Comparar':route==='centros'?'Para centros':'Recursos'} · Brújula`;document.querySelectorAll('[data-nav]').forEach(link=>link.setAttribute('aria-current',link.dataset.nav===route?'page':'false'));const navCount=document.querySelector('#nav-count');navCount.textContent=chosen.size;navCount.hidden=chosen.size===0;if(route==='explorar')renderResults()}
function renderResults(){const found=filteredJobs();document.querySelector('#cards').innerHTML=found.map(tile).join('');document.querySelector('#count').textContent=`${found.length} ${found.length===1?'profesión':'profesiones'}`;document.querySelector('#empty').hidden=found.length!==0;document.querySelector('#inline-count').textContent=`(${chosen.size})`}
function navigate(url){if(url===location.pathname+location.search)return;const update=()=>{history.pushState({},'',url);render();scrollTo(0,0);app.focus({preventScroll:true})};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(update);else update()}
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(link&&link.origin===location.origin&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&!event.altKey&&link.target!=='_blank'){event.preventDefault();navigate(link.pathname+link.search);return}const button=event.target.closest('[data-choose]');if(button){const id=button.dataset.choose;if(chosen.has(id))chosen.delete(id);else if(chosen.size<2)chosen.add(id);render()}});
document.addEventListener('input',event=>{if(event.target.id==='search'){filters.query=event.target.value;renderResults()}});
document.addEventListener('change',event=>{if(event.target.id==='sector'||event.target.id==='stage'){filters[event.target.id]=event.target.value;renderResults()}});
addEventListener('popstate',()=>{render();scrollTo(0,0)});
render();
